def _messages_to_payload(messages: list[Message]) -> list[dict]:
    """Список Message → список dict {role, content} для тела запроса."""
    return [{"role": m.role, "content": m.content} for m in messages]

def _clamp_int(value: object, lo: int, hi: int) -> int:
    """Привести value к int и зажать в [lo, hi]; при ошибке разбора — lo."""
    try:
        n = int(value)  # type: ignore[arg-type]
    except (TypeError, ValueError):
        return lo
    return max(lo, min(hi, n))

def sliding_window(messages: list[Message], n: int = 10) -> list[Message]:
    """Последние n сообщений; системное (если первое) сохраняется всегда."""
    if not messages:
        return []
    head: list[Message] = []
    rest = messages
    if messages[0].role == "system":
        head = [messages[0]]
        rest = messages[1:]
    return head + rest[-n:]

