def _bearer_token(auth_header: str | None) -> str | None:
    """Достать токен из 'Authorization: Bearer <token>' или None."""
    if not auth_header:
        return None
    prefix = "Bearer "
    if not auth_header.startswith(prefix):
        return None
    token = auth_header[len(prefix) :].strip()
    return token or None

