def _dedup_keep_order(items: list[str]) -> list[str]:
    """Убрать дубли, сохранив порядок первого появления."""
    seen: set[str] = set()
    out: list[str] = []
    for item in items:
        if item not in seen:
            seen.add(item)
            out.append(item)
    return out
